window.AdAstraImageDetails={"assets/cielo/foto/Jupiter.jpg":{"points":[{"x":36.0,"y":37.0,"title":"Bande di nubi","text":"Le fasce chiare e scure appartengono all’atmosfera di Giove: non sono continenti su una superficie solida."},{"x":72.0,"y":48.0,"title":"Verso la notte","text":"Il lato poco illuminato indica la geometria della luce solare, non il bordo fisico del pianeta."}]},"assets/cielo/foto/Moon.jpg":{"points":[{"x":44.0,"y":40.0,"title":"Mari lunari","text":"Le regioni scure sono pianure basaltiche, chiamate mari per tradizione: non sono distese d’acqua."},{"x":57.0,"y":75.0,"title":"Altopiani e crateri","text":"L’aspetto di rilievi e crateri dipende anche dall’illuminazione."}]},"assets/cielo/foto/Neptune.jpg":{"points":[{"x":51.0,"y":44.0,"title":"Nubi chiare","text":"Le strutture luminose si distinguono sul disco blu. Una sola foto non misura le velocità dei venti."},{"x":51.0,"y":68.0,"title":"Atmosfera","text":"Il disco mostra gas e nubi, non una crosta rocciosa."}]},"assets/cielo/foto/Saturn.jpg":{"points":[{"x":24.0,"y":50.0,"title":"Anelli","text":"Gli anelli sono formati da moltissimi frammenti, soprattutto ghiacciati, non da un foglio continuo."},{"x":53.0,"y":49.0,"title":"Il globo di Saturno","text":"Il pianeta è distinto dagli anelli. La prospettiva comprime gli anelli in un’ellisse apparente."}]},"assets/cielo/foto/Uranus.jpg":{"points":[{"x":50.0,"y":42.0,"title":"Disco poco contrastato","text":"Le nubi appaiono quasi uniformi in questa ripresa. Altre bande spettrali mostrano dettagli differenti."},{"x":84.0,"y":60.0,"title":"Bordo del pianeta","text":"La fotografia è una proiezione del globo e non ne mostra l’interno."}]},"assets/cielo/foto/costellazione-Cas.jpg":{"points":[{"x":50.0,"y":52.0,"title":"Campo di Cassiopea","text":"La foto non ha linee sovrapposte: confronta posizioni e brillantezze con una carta."},{"x":56.0,"y":35.0,"title":"Fondo stellare","text":"Una fotografia registra stelle deboli che a occhio nudo possono scomparire nel chiarore."}]},"assets/cielo/foto/costellazione-Cyg.jpg":{"points":[{"x":41.0,"y":48.0,"title":"Fascia della Via Lattea","text":"Guardando lungo il disco galattico si sovrappongono molte stelle e nubi."},{"x":38.0,"y":31.0,"title":"Fasce più scure","text":"Le polveri oscurano la luce retrostante: una regione scura non è necessariamente vuota."}]},"assets/cielo/foto/costellazione-Ori.jpg":{"points":[{"x":49.9,"y":61.6,"title":"Cintura di Orione","text":"Tre stelle quasi allineate sono un riferimento apparente: non hanno necessariamente la stessa distanza."},{"x":50.8,"y":70.8,"title":"Regione della Spada","text":"Sotto la Cintura si trovano stelle e nebulosità, più evidenti in fotografia che a occhio nudo."}]},"assets/cielo/foto/costellazione-Tau.jpg":{"points":[{"x":56.0,"y":56.0,"title":"Regione del Toro","text":"Le relazioni angolari aiutano a orientarsi. La vicinanza sulla pagina non dà la distanza nello spazio."},{"x":22.0,"y":61.0,"title":"Strutture diffuse","text":"Una costellazione è una regione del cielo: non tutto ciò che contiene appartiene a un unico oggetto fisico."}]},"assets/cielo/foto/eclissiLuna.jpg":{"points":[{"x":51.0,"y":49.0,"title":"Luna nell’ombra","text":"La Terra intercetta la luce solare diretta. La luce filtrata e deviata dall’atmosfera può colorare il disco di rosso."},{"x":59.0,"y":64.0,"title":"Illuminazione non uniforme","text":"Il passaggio nell’ombra cambia nel tempo. Eclissi e fase ordinaria sono fenomeni diversi."}]},"assets/lezioni/47tuc-globulare.jpg":{"points":[{"x":50.0,"y":50.0,"title":"Centro affollato","text":"Le stelle si sovrappongono in proiezione: non significa che si tocchino."},{"x":69.0,"y":37.0,"title":"Regioni esterne","text":"Qui si separano meglio i punti. L’appartenenza all’ammasso richiede altre misure oltre alla foto."}]},"assets/lezioni/abell1689-galassie.jpg":{"points":[{"x":48.0,"y":55.0,"title":"Galassie dell’ammasso","text":"Molte forme diffuse sono galassie: ognuna contiene moltissime stelle."},{"x":66.5,"y":37.5,"title":"Archi sottili","text":"La lente gravitazionale dell’ammasso deforma immagini di sorgenti più lontane: non sono ponti materiali."}]},"assets/lezioni/adattatore.jpg":{"points":[{"x":50.0,"y":25.0,"title":"Anello di collegamento","text":"L’adattatore unisce attacchi compatibili. Forma simile non garantisce uguali diametro e passo."},{"x":54.0,"y":73.0,"title":"Spessore e appoggio","text":"Il componente contribuisce alla distanza fra le parti: non si misura lo spessore da questa prospettiva."}]},"assets/lezioni/andromeda.jpg":{"points":[{"x":20.0,"y":58.0,"title":"Centro luminoso","text":"Qui si concentra molta luce stellare. Anche risposta e trattamento dei dati influenzano la brillantezza nella foto."},{"x":59.0,"y":54.0,"title":"Bande di polvere","text":"Le polveri nascondono parte delle stelle retrostanti: non sono aperture vuote nella galassia."}]},"assets/lezioni/archivio-digitale.jpg":{"points":[{"x":20.0,"y":46.0,"title":"Archivio digitale","text":"L’astronomia conserva dati e metadati. Una sala di server non mostra il contenuto di uno specifico catalogo."},{"x":77.0,"y":48.0,"title":"Infrastruttura","text":"Alimentazione, rete e raffreddamento sostengono il lavoro sui dati."}]},"assets/lezioni/arcobaleno-doppio-cipro.jpg":{"points":[{"x":59.0,"y":50.0,"title":"Arco primario","text":"La luce subisce rifrazione, riflessione interna e nuova rifrazione nelle gocce."},{"x":65.0,"y":20.0,"title":"Arco secondario","text":"Due riflessioni interne producono un arco esterno più debole con ordine dei colori invertito."}]},"assets/lezioni/astronauti-hubble.jpg":{"points":[{"x":46.0,"y":39.0,"title":"Intervento tecnico","text":"Osservare dipende anche da montaggio e manutenzione: qui si lavora sul telescopio nello spazio."},{"x":36.0,"y":77.0,"title":"Struttura di sostegno","text":"La meccanica deve conservare l’allineamento delle ottiche. Questa non è una sezione ottica."}]},"assets/lezioni/aurora-iss-2025.jpg":{"points":[{"x":42.0,"y":49.0,"title":"Fascia aurorale","text":"Atomi e molecole eccitati emettono nell’alta atmosfera. Non è una nube illuminata dal basso."},{"x":80.0,"y":47.0,"title":"Strutture della stazione","text":"Gli elementi scuri in primo piano appartengono al veicolo spaziale, non all’aurora."}]},"assets/lezioni/betelgeuse-alma-2026.jpg":{"points":[{"x":52.0,"y":47.0,"title":"Stella risolta","text":"L’osservazione ALMA di riferimento risolve Betelgeuse. Con un piccolo telescopio le stelle restano normalmente puntiformi."},{"x":51.0,"y":66.0,"title":"Variazioni di brillantezza","text":"La rappresentazione del segnale non equivale al colore percepito dall’occhio."}]},"assets/lezioni/binocolo-prismi-tetto.jpg":{"points":[{"x":75.0,"y":63.0,"title":"Obiettivi","text":"Le due lenti anteriori raccolgono luce. Il loro diametro è distinto dall’ingrandimento."},{"x":48.0,"y":35.0,"title":"Messa a fuoco","text":"La rotella centrale regola il fuoco. Dove prevista, la regolazione diottrica compensa differenze fra gli occhi."}]},"assets/lezioni/binocolo.jpg":{"points":[{"x":64.0,"y":46.0,"title":"Obiettivi","text":"La sigla del modello, non la prospettiva della foto, stabilisce il diametro delle lenti."},{"x":43.0,"y":33.0,"title":"Comando di fuoco","text":"La manopola rende nitida l’immagine; l’apertura fra gli oculari va adattata agli occhi."}]},"assets/lezioni/camera.jpg":{"points":[{"x":50.0,"y":55.0,"title":"Obiettivo fotografico","text":"Forma l’immagine sul sensore. La focale influisce sull’ampiezza del campo."},{"x":37.0,"y":35.0,"title":"Corpo digitale","text":"Questo esempio è una fotocamera digitale, non a pellicola. La lezione confronta tipologie di camere."}]},"assets/lezioni/carina.jpg":{"points":[{"x":53.0,"y":50.0,"title":"Colonne di gas e polveri","text":"Le parti scure assorbono luce retrostante; i bordi brillanti sono irradiati."},{"x":48.0,"y":18.0,"title":"Strutture illuminate","text":"I colori della composizione vanno letti secondo le bande osservate dichiarate dalla fonte."}]},"assets/lezioni/carta-lettura-originale.png":{"points":[{"x":49.0,"y":48.0,"title":"Zenit al centro","text":"La mappa è altazimutale: il centro è sopra la testa, non coincide in generale con il polo."},{"x":56.0,"y":74.0,"title":"Cerchi di altezza","text":"Il raggio dipende dalla distanza zenitale. Qui le direzioni sono assegnate, non effemeridi di una data."}]},"assets/lezioni/catalogo-coordinate-originale.png":{"points":[{"x":42.0,"y":30.0,"title":"Sorgente e incertezza","text":"Il cerchio rappresenta un’incertezza assegnata, non le dimensioni fisiche della stella."},{"x":51.0,"y":83.0,"title":"Coordinate locali","text":"Gli scarti sono angoli. Per l’ascensione retta nel piano tangente entra anche il fattore coseno della declinazione."}]},"assets/lezioni/cavalletto.jpg":{"points":[{"x":42.0,"y":51.0,"title":"Testa del treppiede","text":"Collega camera e gambe. Bloccandola si conserva l’inquadratura durante la posa."},{"x":56.0,"y":78.0,"title":"Sostegno e giunti","text":"La stabilità dipende da appoggi e serraggi; la fotografia non misura la rigidità del sistema."}]},"assets/lezioni/cometa67p-navcam.jpg":{"points":[{"x":49.0,"y":47.0,"title":"Nucleo della cometa","text":"Il corpo solido ha forma irregolare. Non è una stella o una sfera di gas."},{"x":65.0,"y":18.0,"title":"Attività","text":"Il nucleo rilascia materiale. Il corpo solido e una coda estesa non sono la stessa cosa."}]},"assets/lezioni/correttore.jpg":{"points":[{"x":51.0,"y":31.0,"title":"Elemento ottico","text":"Il correttore modifica il fascio secondo un progetto specifico: non è un oculare generico."},{"x":49.0,"y":74.0,"title":"Connessione","text":"Attacco e distanza dal sensore devono rispettare le specifiche del sistema."}]},"assets/lezioni/eclisse-totale-madras.jpg":{"points":[{"x":49.0,"y":48.0,"title":"Disco lunare","text":"La Luna copre il disco brillante del Sole nella geometria della totalità."},{"x":54.0,"y":25.0,"title":"Corona solare","text":"La tenue atmosfera esterna emerge nella fotografia. La foto non sostituisce le procedure di sicurezza per osservare il Sole."}]},"assets/lezioni/effemeridi-tempo-originale.png":{"points":[{"x":51.0,"y":33.0,"title":"Ora UTC","text":"UTC è un riferimento comune per identificare l’istante; non cambia con l’ora legale."},{"x":51.0,"y":63.0,"title":"Giorno locale successivo","text":"Aggiungere il fuso può cambiare la data: conserva insieme giorno, ora e fuso."}]},"assets/lezioni/encelado-pennacchi-cassini.jpg":{"points":[{"x":17.0,"y":91.0,"title":"Bordo di Encelado","text":"La parte poco illuminata della superficie è in controluce."},{"x":28.0,"y":78.0,"title":"Pennacchi","text":"Il materiale espulso dal satellite è visibile contro il fondo scuro: non significa che tutta la superficie sia gassosa."}]},"assets/lezioni/esopianeta-2m1207.jpg":{"points":[{"x":62.0,"y":45.0,"title":"Sorgente primaria","text":"La sorgente principale è una nana bruna, non una stella simile al Sole."},{"x":17.7,"y":69.0,"title":"Compagno debole","text":"La separazione sulla foto è proiettata: non fornisce la distanza tridimensionale completa."}]},"assets/lezioni/focheggiatore.jpg":{"points":[{"x":49.0,"y":34.0,"title":"Tubo mobile","text":"Il focheggiatore sposta una parte della catena lungo il cammino ottico per trovare la nitidezza."},{"x":25.0,"y":49.0,"title":"Manopola","text":"Una regolazione delicata limita le vibrazioni. Il seeing può cambiare il dettaglio anche a fuoco corretto."}]},"assets/lezioni/gaia-diagramma-hr.jpg":{"points":[{"x":43.0,"y":58.0,"title":"Sequenza principale","text":"Il grande addensamento collega colore e luminosità: non è una traiettoria seguita da tutte le stelle."},{"x":57.0,"y":30.0,"title":"Giganti","text":"Una stella relativamente fredda può essere molto luminosa perché ha un grande raggio."}]},"assets/lezioni/hh24-getti-protostellari.jpg":{"points":[{"x":49.0,"y":47.0,"title":"Regione oscurata","text":"Polveri e materiale circumstellare nascondono la sorgente centrale."},{"x":54.0,"y":27.0,"title":"Getto protostellare","text":"L’emissione in una direzione preferita aiuta a studiare la formazione della stella: non è un raggio solido."}]},"assets/lezioni/hltauri-alma-disco.jpg":{"points":[{"x":49.0,"y":51.0,"title":"Disco circumstellare","text":"ALMA registra emissione millimetrica. Il colore rappresenta il dato, non una visione dell’occhio."},{"x":66.0,"y":46.0,"title":"Anelli e intervalli","text":"Le strutture indicano variazioni di emissione e materiale; non identificano un pianeta in ogni intervallo."}]},"assets/lezioni/hubble.jpg":{"points":[{"x":49.0,"y":45.0,"title":"Telescopio spaziale","text":"Ottica, struttura e puntamento lavorano insieme per registrare il cielo."},{"x":60.0,"y":76.0,"title":"Terra sotto lo strumento","text":"Dall’orbita si evitano diversi limiti atmosferici delle osservazioni dal suolo."}]},"assets/lezioni/luna-diurna-wasatch.jpg":{"points":[{"x":40.0,"y":43.0,"title":"Luna di giorno","text":"La Luna si può vedere anche nel cielo diurno: non compare soltanto di notte."},{"x":45.0,"y":74.0,"title":"Paesaggio","text":"Le montagne nascondono alcune direzioni: il profilo del terreno differisce dall’orizzonte geometrico."}]},"assets/lezioni/luna-rifrazione-iss.jpg":{"points":[{"x":49.0,"y":53.0,"title":"Disco lunare","text":"Vicino all’orizzonte la luce attraversa molta atmosfera. La rifrazione può alterare la forma apparente."},{"x":50.0,"y":65.0,"title":"Atmosfera terrestre","text":"La fascia azzurra rende riconoscibile il bordo atmosferico nella vista dallo spazio."}]},"assets/lezioni/luna-torva.png":{"points":[{"x":51.0,"y":74.0,"title":"Terminatore","text":"Il confine fra luce e ombra esalta le ombre dei rilievi. Non è il bordo fisico della Luna."},{"x":49.0,"y":35.0,"title":"Mari","text":"Le pianure basaltiche scure cambiano contrasto con l’illuminazione."}]},"assets/lezioni/m11-ammasso-aperto.jpg":{"points":[{"x":51.0,"y":50.0,"title":"Stelle dell’ammasso","text":"L’addensamento è un indizio. Per confermare i membri servono distanze e movimenti."},{"x":74.0,"y":29.0,"title":"Stelle di campo","text":"Non tutti gli oggetti lungo la stessa linea di vista appartengono al gruppo."}]},"assets/lezioni/m33-cielo-profondo.jpg":{"points":[{"x":49.0,"y":49.0,"title":"Centro di M33","text":"Ogni regione diffusa raccoglie la luce di moltissime stelle della galassia."},{"x":69.0,"y":36.0,"title":"Strutture del disco","text":"Luce e polveri rendono leggibile il disco. La foto non mostra direttamente le velocità."}]},"assets/lezioni/m51-struttura-galassia.jpg":{"points":[{"x":34.0,"y":67.0,"title":"Bracci","text":"Stelle, gas e polveri delineano i bracci: non sono stecche rigide."},{"x":81.0,"y":27.0,"title":"Compagna","text":"L’oggetto vicino interagisce con il sistema; proiezione e distanza fisica restano concetti distinti."}]},"assets/lezioni/m87-eht-2019.jpg":{"points":[{"x":50.0,"y":51.0,"title":"Regione centrale scura","text":"EHT ricostruisce emissione radio: la regione scura è collegata all’ombra del buco nero, non a una superficie materiale."},{"x":46.0,"y":60.0,"title":"Anello luminoso","text":"Plasma e deviazione gravitazionale della luce formano l’aspetto dell’emissione. Il colore rende leggibile il segnale radio."}]},"assets/lezioni/macchia-solare-sdo.jpg":{"points":[{"x":45.0,"y":68.0,"title":"Macchie solari","text":"Sono più fredde della fotosfera circostante, pur restando molto calde."},{"x":52.0,"y":35.0,"title":"Fotosfera","text":"È la regione da cui emerge gran parte della luce visibile: non è una crosta solida."}]},"assets/lezioni/marte-hottah-curiosity.jpg":{"points":[{"x":47.0,"y":54.0,"title":"Strati di roccia","text":"Conservano informazioni sull’ambiente passato. La fotografia non data da sola il deposito."},{"x":62.0,"y":35.0,"title":"Sporgenza erosa","text":"Osservare una forma e interpretare il processo che l’ha prodotta sono due passaggi distinti."}]},"assets/lezioni/meteorite-hoba.jpg":{"points":[{"x":50.0,"y":52.0,"title":"Meteorite","text":"È materiale extraterrestre arrivato al suolo. La meteora è invece il fenomeno luminoso atmosferico."},{"x":66.0,"y":67.0,"title":"Superficie alterata","text":"L’ambiente cambia l’aspetto esterno. Il solo colore non certifica l’origine di un campione."}]},"assets/lezioni/misura-cielo-sqm.jpg":{"points":[{"x":50.0,"y":30.0,"title":"Sensore fotometrico","text":"Misura il fondo in un campo e in una banda di risposta definiti."},{"x":53.0,"y":75.0,"title":"Condizioni della misura","text":"Direzione, ora, Luna e meteo vanno registrati. Un numero isolato non assegna una classe Bortle."}]},"assets/lezioni/montatura.jpg":{"points":[{"x":49.0,"y":38.0,"title":"Testa equatoriale","text":"Il sostegno è organizzato attorno a un asse polare."},{"x":31.0,"y":71.0,"title":"Contrappeso","text":"Bilancia il carico: non è il motore che muove il telescopio."}]},"assets/lezioni/nettuno-webb-nircam.jpg":{"points":[{"x":50.0,"y":48.0,"title":"Nettuno nell’infrarosso","text":"Webb osserva bande diverse dal visibile. Non confrontare il colore direttamente con la foto Voyager blu."},{"x":29.0,"y":53.0,"title":"Anelli deboli","text":"Emergono in bande e condizioni appropriate: non sono un alone atmosferico."}]},"assets/lezioni/newton.jpg":{"points":[{"x":49.0,"y":29.0,"title":"Tubo del riflettore","text":"Un Newton forma l’immagine con specchi: lo schema ottico è distinto dal tipo di montatura."},{"x":53.0,"y":75.0,"title":"Sostegno","text":"La meccanica orienta il tubo e sostiene il carico; la fotografia non certifica una prestazione."}]},"assets/lezioni/ngc6302-involucro-stellare.jpg":{"points":[{"x":55.0,"y":53.0,"title":"Centro oscurato","text":"Il materiale più denso può nascondere la stella responsabile della nebulosa."},{"x":53.0,"y":23.0,"title":"Lobi di gas","text":"Il gas espulso emette luce. Il nome nebulosa planetaria non significa nascita di pianeti."}]},"assets/lezioni/oculare.jpg":{"points":[{"x":49.0,"y":19.0,"title":"Lato dell’occhio","text":"L’oculare permette di osservare l’immagine formata dal telescopio."},{"x":49.0,"y":79.0,"title":"Barilotto","text":"La misura meccanica del barilotto non è la lunghezza focale dell’oculare."}]},"assets/lezioni/oculari-confronto.png":{"points":[{"x":62.0,"y":32.0,"title":"Oculari diversi","text":"La forma esterna non stabilisce da sola l’ingrandimento: contano le focali abbinate."},{"x":52.0,"y":76.0,"title":"Accessori","text":"Prima di montare verifica compatibilità e serraggi. Non sono tutti acquisti obbligatori."}]},"assets/lezioni/orione-fotografico.jpg":{"points":[{"x":49.0,"y":50.0,"title":"Cintura di Orione","text":"Le tre stelle quasi allineate aiutano a orientare il campo."},{"x":31.5,"y":50.4,"title":"Nebulosità","text":"La ripresa profonda mostra luce debole che non è garantita nella visione a occhio nudo."}]},"assets/lezioni/osservatori-notte-2024.jpg":{"points":[{"x":61.0,"y":70.0,"title":"Area osservativa","text":"Organizza attrezzature e passaggi liberi. La foto non misura il buio del sito."},{"x":88.0,"y":69.0,"title":"Luci locali","text":"Schermare le luci evita di abbagliare gli altri e limita luce inutile nell’ambiente."}]},"assets/lezioni/paesaggio-namibia.jpg":{"points":[{"x":51.0,"y":25.0,"title":"Via Lattea panoramica","text":"La curvatura dell’arco dipende anche dalla proiezione di un campo molto ampio."},{"x":23.0,"y":68.0,"title":"Paesaggio","text":"Leggi il metodo di ripresa per capire come cielo e terreno sono stati combinati."}]},"assets/lezioni/perseide-vlt-2010.jpg":{"points":[{"x":41.0,"y":36.0,"title":"Traccia meteorica","text":"La durata della posa e quella del singolo fenomeno luminoso non sono la stessa cosa."},{"x":44.0,"y":74.0,"title":"Osservatorio","text":"Il terreno fermo è un riferimento per leggere il moto apparente nel cielo."}]},"assets/lezioni/piano-notte-originale.png":{"points":[{"x":35.0,"y":31.0,"title":"Curve di altezza","text":"Sono direzioni calcolate per astri ipotetici, non previsioni per una notte reale."},{"x":55.0,"y":67.0,"title":"Soglia","text":"Una soglia operativa non calcola atmosfera, Luna o ostacoli del tuo sito."}]},"assets/lezioni/planck-fondo-microonde.jpg":{"points":[{"x":46.0,"y":48.0,"title":"Fondo cosmico","text":"I colori indicano piccole differenze di temperatura alle microonde: non sono galassie colorate."},{"x":72.0,"y":46.0,"title":"Proiezione del cielo","text":"L’ovale è una proiezione cartografica della sfera, non la forma dell’Universo."}]},"assets/lezioni/posa-tracce.jpg":{"points":[{"x":42.0,"y":42.0,"title":"Scie stellari","text":"La posa registra il cambiamento di direzione apparente dovuto alla rotazione terrestre."},{"x":78.0,"y":40.0,"title":"Tracce diverse","text":"Una traccia non concorde richiede un’identificazione separata: confronta la descrizione della fonte."}]},"assets/lezioni/preparazione-serata-2024.jpg":{"points":[{"x":42.0,"y":49.0,"title":"Preparazione","text":"Si controllano collegamenti e sostegno prima del buio; la scena non sostituisce un manuale."},{"x":48.0,"y":73.0,"title":"Appoggio","text":"Superficie, serraggi e ingombri vanno verificati prima di osservare."}]},"assets/lezioni/revisione-20261028/ngc1300-hubble.jpg":{"points":[{"x":48.0,"y":49.0,"title":"Barra centrale","text":"La distribuzione stellare allungata distingue la galassia barrata: non è una sbarra rigida."},{"x":25.0,"y":66.0,"title":"Bracci","text":"La foto mostra strutture di luce e polvere, non una misura del moto nel tempo."}]},"assets/lezioni/revisione-20261028/stagioni-epic.jpg":{"points":[{"x":25.0,"y":25.0,"title":"Globo illuminato","text":"Nuvole, illuminazione e prospettiva non vanno confuse con il meccanismo delle stagioni."},{"x":73.0,"y":73.0,"title":"Confrontare le date","text":"Per spiegare le stagioni serve la geometria dell’asse e dell’orbita, non la quantità di nubi."}]},"assets/lezioni/revisione-20261028/tramonto-orbitale-iss.jpg":{"points":[{"x":50.0,"y":46.0,"title":"Bordo atmosferico","text":"La vista radente rende evidente la sottile atmosfera terrestre."},{"x":50.0,"y":69.0,"title":"Passaggio al buio","text":"Il confine dipende dalla direzione del Sole e non è fisso sul terreno."}]},"assets/lezioni/rifrattore.jpg":{"points":[{"x":53.0,"y":34.0,"title":"Obiettivo","text":"La lente raccoglie luce e forma l’immagine; il fuoco si regola all’altra estremità."},{"x":43.0,"y":68.0,"title":"Montatura","text":"Il modo di orientare il tubo è distinto dallo schema ottico del rifrattore."}]},"assets/lezioni/rs-puppis-cefeide.jpg":{"points":[{"x":48.0,"y":51.0,"title":"RS Puppis","text":"La Cefeide varia luminosità. Il periodo, con una calibrazione, aiuta a stimare la luminosità intrinseca."},{"x":54.0,"y":28.0,"title":"Materia circostante","text":"La luce diffusa rivela materiale attorno alla stella; questa foto non è una ripresa della pulsazione nel tempo."}]},"assets/lezioni/scatto.jpg":{"points":[{"x":52.0,"y":35.0,"title":"Comando remoto","text":"Avviare lo scatto senza toccare la camera limita le vibrazioni; funzioni e compatibilità variano."},{"x":49.0,"y":12.0,"title":"Cavo","text":"Il cavo trasmette un comando: non è il percorso seguito dalla luce."}]},"assets/lezioni/sirio-compagna-hubble.jpg":{"points":[{"x":28.2,"y":74.3,"title":"Sirio B","text":"La compagna più debole è visibile nella ripresa Hubble. Il contrasto con Sirio A ne rende difficile l’osservazione."},{"x":53.0,"y":45.0,"title":"Diffrazione e alone","text":"Punte e alone dipendono anche dalla risposta ottica, non sono raggi emessi con quelle forme."}]},"assets/lezioni/smart-seestar-s50.jpg":{"points":[{"x":54.0,"y":25.0,"title":"Corpo ottico","text":"Lo smart telescope integra ottica, sensore e movimenti. Qui è un Seestar S50, non una versione successiva."},{"x":51.0,"y":66.0,"title":"Controllo integrato","text":"Automazione e telefono semplificano operazioni ma non cancellano i limiti del cielo o del sostegno."}]},"assets/lezioni/smartphone.jpg":{"points":[{"x":53.0,"y":35.0,"title":"Fotocamera del telefono","text":"Il piccolo sensore può registrare il cielo. Per pose lunghe occorre fissare il dispositivo."},{"x":52.0,"y":62.0,"title":"Impugnatura","text":"Tenere in mano è diverso dall’usare un cavalletto: le vibrazioni contano prima dell’elaborazione."}]},"assets/lezioni/spettro-solare-osservato.jpg":{"points":[{"x":45.0,"y":35.0,"title":"Righe scure","text":"Le righe di assorbimento portano informazioni sugli atomi lungo il cammino della luce."},{"x":52.0,"y":70.0,"title":"Spettro impaginato","text":"Le bande sono disposte su più righe per mostrare dettagli: non sono arcobaleni simultanei nel cielo."}]},"assets/lezioni/stellarium-percorso-originale.png":{"points":[{"x":51.0,"y":21.0,"title":"Luogo e istante","text":"Un planetario richiede sito, data e fuso corretti prima del confronto col cielo."},{"x":51.0,"y":79.0,"title":"Riscontro","text":"Carta, cielo e appunti si confrontano alla fine. La figura è un percorso, non una schermata reale."}]},"assets/lezioni/telescopi-osservazione-2025.jpg":{"points":[{"x":31.0,"y":47.0,"title":"Sistema integrato","text":"Nel corpo compatto sono riunite funzioni che un sistema tradizionale tiene separate."},{"x":72.0,"y":35.0,"title":"Ottica e montatura","text":"Distingui il tubo dal sostegno. La foto non dimostra prestazioni uguali fra i due sistemi."}]},"assets/lezioni/terra-blue-marble.jpg":{"points":[{"x":51.0,"y":44.0,"title":"Globo terrestre","text":"È una vista esterna: l’orizzonte dell’osservatore è invece un piano locale tangente."},{"x":54.0,"y":71.0,"title":"Nubi e superficie","text":"La fotografia combina aspetti atmosferici e geografici; non misura da sola la rotazione."}]},"assets/lezioni/terra-voyager-pia23645.jpg":{"points":[{"x":59.5,"y":52.0,"title":"La Terra lontana","text":"Il minuscolo punto va identificato con la fonte: non è il fascio luminoso nel suo insieme."},{"x":58.0,"y":35.0,"title":"Luce diffusa strumentale","text":"Le bande non sono strutture che collegano pianeti: sono luce diffusa nell’apparato fotografico."}]},"assets/lezioni/tracce-movimento-wesson.jpg":{"points":[{"x":52.0,"y":44.0,"title":"Centro delle scie","text":"Gli archi sono centrati vicino al polo celeste della ripresa, non necessariamente allo zenit."},{"x":31.0,"y":68.0,"title":"Archi ampi","text":"Più lontano dal polo i cerchi sono più grandi. Non è un cambiamento della declinazione."}]},"assets/lezioni/tracce-paranal-fondamenti.jpg":{"points":[{"x":55.0,"y":47.0,"title":"Laser dell’osservatorio","text":"Il fascio è uno strumento dell’ottica adattiva: non è una scia stellare."},{"x":37.0,"y":41.0,"title":"Scie stellari","text":"La posa registra il moto apparente: non sono orbite materiali attorno al telescopio."}]},"assets/lezioni/tracce-stellari.jpg":{"points":[{"x":56.0,"y":50.0,"title":"Rotazione apparente","text":"Le stelle mantengono circa la distanza angolare dal polo mentre cambiano direzione locale."},{"x":26.0,"y":79.0,"title":"Cupola ferma","text":"Il confronto fra terreno fermo e archi luminosi rende leggibile il tempo trascorso."}]},"assets/lezioni/trifida-emissione-polveri.jpg":{"points":[{"x":48.0,"y":58.0,"title":"Gas emittente","text":"Il gas può emettere in righe specifiche: interpreta i colori secondo i filtri della fonte."},{"x":42.0,"y":65.0,"title":"Polveri","text":"Le strisce scure sono materia che nasconde luce, non vuoti."}]},"assets/lezioni/tycho-raggi-x-2019.jpg":{"points":[{"x":52.0,"y":50.0,"title":"Resto di supernova","text":"L’emissione in raggi X non è visibile all’occhio; qui è resa in una composizione di dati."},{"x":64.0,"y":29.0,"title":"Strutture interne","text":"Una sola immagine non fornisce tutte le velocità o l’età del resto."}]},"assets/lezioni/tycho-rilievo-lro.jpg":{"points":[{"x":58.0,"y":69.0,"title":"Picco illuminato","text":"La luce radente fa risaltare i rilievi; la quota non si legge come una lunghezza sul foglio."},{"x":40.0,"y":26.0,"title":"Ombra","text":"L’ombra dipende da altezza del rilievo e angolo del Sole. Servono geometria e scala per misurare una quota."}]},"assets/lezioni/uai-polare.png":{"points":[{"x":39.0,"y":51.0,"title":"Grande Carro","text":"Le linee collegano direzioni per aiutare a riconoscere una figura: non sono legami fisici."},{"x":46.3,"y":17.5,"title":"Polare","text":"È vicina al polo nord celeste ma non vi coincide. Questa illustrazione non è una carta quantitativa."}]},"assets/lezioni/velo-resto-supernova.jpg":{"points":[{"x":55.0,"y":50.0,"title":"Filamenti","text":"Il gas emette dopo il passaggio dell’onda d’urto. Nebulose diverse possono avere origini differenti."},{"x":70.0,"y":64.0,"title":"Colori","text":"Dipendono da bande e composizione; non rappresentano la visione senza strumenti."}]},"assets/lezioni/via-lattea-panorama.jpg":{"points":[{"x":51.0,"y":46.0,"title":"Disco visto dall’interno","text":"La fascia è una proiezione di molte stelle e nubi nel piano galattico."},{"x":44.0,"y":48.0,"title":"Polveri scure","text":"Le polveri nascondono parte delle stelle: il centro galattico non è tutto direttamente visibile in ottico."}]},"assets/lezioni/webb-ispezione-2017.jpg":{"points":[{"x":55.0,"y":44.0,"title":"Webb durante le prove","text":"La foto mostra hardware a terra, non il telescopio già operativo nello spazio."},{"x":57.0,"y":74.0,"title":"Supporti di prova","text":"Gli apparati del laboratorio non fanno tutti parte dello strumento che vola."}]},"assets/lezioni/scene-originali-20261028/lezione-1-3.webp":{"points":[{"x":52.0,"y":44.0,"title":"Centro delle scie","text":"Gli archi sono centrati vicino al polo celeste della ripresa, non necessariamente allo zenit."},{"x":31.0,"y":68.0,"title":"Archi ampi","text":"Più lontano dal polo i cerchi sono più grandi. Non è un cambiamento della declinazione."}]},"assets/lezioni/scene-originali-20261028/lezione-10-4.webp":{"points":[{"x":52.0,"y":50.0,"title":"Resto di supernova","text":"L’emissione in raggi X non è visibile all’occhio; qui è resa in una composizione di dati."},{"x":64.0,"y":29.0,"title":"Strutture interne","text":"Una sola immagine non fornisce tutte le velocità o l’età del resto."}]},"assets/lezioni/scene-originali-20261028/lezione-2-3.webp":{"points":[{"x":50,"y":44,"title":"Nucleo illustrato","text":"La sezione è una ricostruzione: l’interno del Sole non è fotografato direttamente."},{"x":68,"y":64,"title":"Fotosfera","text":"La superficie apparente emette gran parte della luce visibile. Le macchie sono più fredde dell’ambiente circostante."}]},"assets/lezioni/scene-originali-20261028/lezione-2-5.webp":{"points":[{"x":60,"y":48,"title":"Picco centrale","text":"La ricostruzione mostra un rilievo illuminato dalla luce radente."},{"x":40,"y":26,"title":"Ombra","text":"L’ombra dipende da rilievo e altezza del Sole. Senza una scala la sua lunghezza grafica non dà una quota."}]},"assets/lezioni/scene-originali-20261028/lezione-3-2.webp":{"points":[{"x":47.0,"y":54.0,"title":"Strati di roccia","text":"Conservano informazioni sull’ambiente passato. La fotografia non data da sola il deposito."},{"x":62.0,"y":35.0,"title":"Sporgenza erosa","text":"Osservare una forma e interpretare il processo che l’ha prodotta sono due passaggi distinti."}]},"assets/lezioni/scene-originali-20261028/lezione-3-3.webp":{"points":[{"x":50.0,"y":48.0,"title":"Nettuno nell’infrarosso","text":"Webb osserva bande diverse dal visibile. Non confrontare il colore direttamente con la foto Voyager blu."},{"x":29.0,"y":53.0,"title":"Anelli deboli","text":"Emergono in bande e condizioni appropriate: non sono un alone atmosferico."}]},"assets/lezioni/scene-originali-20261028/lezione-3-4.webp":{"points":[{"x":38,"y":80,"title":"Superficie ghiacciata","text":"La ricostruzione rende leggibile il rilievo, senza fornire una misura della sua altezza."},{"x":51,"y":33,"title":"Pennacchi illustrati","text":"Il materiale rilasciato è distinto dalla superficie. Intensità e forma della scena non sono dati Cassini."}]},"assets/lezioni/scene-originali-20261028/lezione-3-5.webp":{"points":[{"x":49.0,"y":47.0,"title":"Nucleo della cometa","text":"Il corpo solido ha forma irregolare. Non è una stella o una sfera di gas."},{"x":65.0,"y":18.0,"title":"Attività","text":"Il nucleo rilascia materiale. Il corpo solido e una coda estesa non sono la stessa cosa."}]},"assets/lezioni/scene-originali-20261028/lezione-4-1.webp":{"points":[{"x":49,"y":46,"title":"Regione centrale","text":"Il modello illustra una produzione interna di energia, senza fotografare gli strati."},{"x":65,"y":29,"title":"Strati della stella","text":"Spessori e colori sono illustrativi. La pressione cambia con la profondità e contribuisce al sostegno contro la gravità."}]},"assets/lezioni/scene-originali-20261028/lezione-4-5.webp":{"points":[{"x":49.0,"y":47.0,"title":"Regione oscurata","text":"Polveri e materiale circumstellare nascondono la sorgente centrale."},{"x":54.0,"y":27.0,"title":"Getto protostellare","text":"L’emissione in una direzione preferita aiuta a studiare la formazione della stella: non è un raggio solido."}]},"assets/lezioni/scene-originali-20261028/lezione-4-6.webp":{"points":[{"x":55.0,"y":53.0,"title":"Centro oscurato","text":"Il materiale più denso può nascondere la stella responsabile della nebulosa."},{"x":53.0,"y":23.0,"title":"Lobi di gas","text":"Il gas espulso emette luce. Il nome nebulosa planetaria non significa nascita di pianeti."}]},"assets/lezioni/scene-originali-20261028/lezione-5-1.webp":{"points":[{"x":49.0,"y":49.0,"title":"Centro di M33","text":"Ogni regione diffusa raccoglie la luce di moltissime stelle della galassia."},{"x":69.0,"y":36.0,"title":"Strutture del disco","text":"Luce e polveri rendono leggibile il disco. La foto non mostra direttamente le velocità."}]},"assets/lezioni/scene-originali-20261028/lezione-5-2.webp":{"points":[{"x":51.0,"y":50.0,"title":"Stelle dell’ammasso","text":"L’addensamento è un indizio. Per confermare i membri servono distanze e movimenti."},{"x":74.0,"y":29.0,"title":"Stelle di campo","text":"Non tutti gli oggetti lungo la stessa linea di vista appartengono al gruppo."}]},"assets/lezioni/scene-originali-20261028/lezione-5-3.webp":{"points":[{"x":50.0,"y":50.0,"title":"Centro affollato","text":"Le stelle si sovrappongono in proiezione: non significa che si tocchino."},{"x":69.0,"y":37.0,"title":"Regioni esterne","text":"Qui si separano meglio i punti. L’appartenenza all’ammasso richiede altre misure oltre alla foto."}]},"assets/lezioni/scene-originali-20261028/lezione-5-4.webp":{"points":[{"x":35,"y":65,"title":"Gas emittente","text":"La zona luminosa illustra l’emissione di una nebulosa; non è una misura fotometrica."},{"x":46,"y":54,"title":"Polveri oscuranti","text":"Le zone scure illustrano materiale davanti alla luce retrostante, non un vuoto."}]},"assets/lezioni/scene-originali-20261028/lezione-5-5.webp":{"points":[{"x":55.0,"y":50.0,"title":"Filamenti","text":"Il gas emette dopo il passaggio dell’onda d’urto. Nebulose diverse possono avere origini differenti."},{"x":70.0,"y":64.0,"title":"Colori","text":"Dipendono da bande e composizione; non rappresentano la visione senza strumenti."}]},"assets/lezioni/scene-originali-20261028/lezione-6-1.webp":{"points":[{"x":51.0,"y":46.0,"title":"Disco visto dall’interno","text":"La fascia è una proiezione di molte stelle e nubi nel piano galattico."},{"x":44.0,"y":48.0,"title":"Polveri scure","text":"Le polveri nascondono parte delle stelle: il centro galattico non è tutto direttamente visibile in ottico."}]},"assets/lezioni/scene-originali-20261028/lezione-6-2.webp":{"points":[{"x":34.0,"y":67.0,"title":"Bracci","text":"Stelle, gas e polveri delineano i bracci: non sono stecche rigide."},{"x":81.0,"y":27.0,"title":"Compagna","text":"L’oggetto vicino interagisce con il sistema; proiezione e distanza fisica restano concetti distinti."}]},"assets/lezioni/scene-originali-20261028/lezione-6-4.webp":{"points":[{"x":48,"y":55,"title":"Concentrazione di galassie","text":"Il campo ricostruito rende visibile l’idea di un ammasso, senza identificarne ogni sorgente."},{"x":67,"y":40,"title":"Galassie in proiezione","text":"La vicinanza sulla pagina non misura la distanza fisica. Per le lenti gravitazionali usa anche il modello geometrico della lezione."}]},"assets/lezioni/scene-originali-20261028/lezione-8-2.webp":{"points":[{"x":41.0,"y":36.0,"title":"Traccia meteorica","text":"La durata della posa e quella del singolo fenomeno luminoso non sono la stessa cosa."},{"x":44.0,"y":74.0,"title":"Osservatorio","text":"Il terreno fermo è un riferimento per leggere il moto apparente nel cielo."}]},"assets/lezioni/scene-originali-20261028/lezione-8-3.webp":{"points":[{"x":42,"y":49,"title":"Fascia aurorale","text":"L’emissione ha origine nell’alta atmosfera: non è una nube illuminata da terra."},{"x":53,"y":75,"title":"Bordo terrestre","text":"La ricostruzione mostra una vista orbitale. La fascia luminosa segue la geometria atmosferica, non una superficie solida sospesa."}]},"assets/lezioni/scene-originali-20261028/lezione-8-4.webp":{"points":[{"x":49.0,"y":53.0,"title":"Disco lunare","text":"Vicino all’orizzonte la luce attraversa molta atmosfera. La rifrazione può alterare la forma apparente."},{"x":50.0,"y":65.0,"title":"Atmosfera terrestre","text":"La fascia azzurra rende riconoscibile il bordo atmosferico nella vista dallo spazio."}]},"assets/lezioni/scene-originali-20261028/lezione-1-1.webp":{"points":[{"x":32,"y":57,"title":"Osservatore","text":"Altezza e azimut descrivono il cielo dal luogo di chi osserva."},{"x":71,"y":65,"title":"Orizzonte del paesaggio","text":"Tetti e rilievi possono nascondere direzioni sopra l’orizzonte astronomico."}]},"assets/lezioni/scene-originali-20261028/lezione-1-4.webp":{"points":[{"x":22,"y":58,"title":"Punto di osservazione","text":"Il foro fa osservare dalla stessa posizione. Da qui palline a distanze diverse possono apparire vicine."},{"x":65,"y":53,"title":"Palline nello spazio","text":"Spostando l’occhio cambia la figura apparente; i punti fisici restano fermi."}]},"assets/lezioni/scene-originali-20261028/lezione-4-3.webp":{"points":[{"x":32,"y":55,"title":"Prisma","text":"Separa le lunghezze d’onda per dispersione; non crea gli elementi chimici della sorgente."},{"x":79,"y":45,"title":"Spettro","text":"Posizione e intensità si misurano con dati e calibrazione, non soltanto con un’immagine colorata."}]},"assets/lezioni/scene-originali-20261028/lezione-7-2.webp":{"points":[{"x":44,"y":30,"title":"Binocolo","text":"I due canali ottici portano un’immagine a entrambi gli occhi."},{"x":53,"y":55,"title":"Appoggio possibile","text":"Un supporto stabile, se disponibile e sicuro, riduce le vibrazioni. La scena non è una misura dell’ingrandimento."}]},"assets/lezioni/scene-originali-20261028/lezione-7-3.webp":{"points":[{"x":66,"y":27,"title":"Obiettivo","text":"L’apertura influisce sulla luce raccolta e sul limite di diffrazione."},{"x":32,"y":48,"title":"Fuoco","text":"Il piano dell’immagine deve cadere nella posizione richiesta dall’oculare o dal sensore."}]},"assets/lezioni/scene-originali-20261028/lezione-7-5.webp":{"points":[{"x":20,"y":41,"title":"Lampada vicina","text":"Una luce non schermata può abbagliare anche con un cielo sereno."},{"x":58,"y":70,"title":"Adattamento al buio","text":"Controlla le luci del sito: il solo colore di una lampada non ne annulla gli effetti."}]},"assets/lezioni/scene-originali-20261028/lezione-7-6.webp":{"points":[{"x":48,"y":68,"title":"Quaderno","text":"Annotare luogo, ora, condizioni e osservazione permette di confrontare serate diverse."},{"x":58,"y":55,"title":"Luce rossa tenue","text":"Illumina solo gli appunti e non dirigere la lampada verso gli occhi altrui."}]},"assets/lezioni/scene-originali-20261028/lezione-8-1.webp":{"points":[{"x":38,"y":48,"title":"Esterno del campione","text":"Una pietra scura non è automaticamente un meteorite: servono verifiche indipendenti."},{"x":70,"y":59,"title":"Interno","text":"Analisi e sezioni mostrano strutture invisibili all’esterno: non si classifica dal colore dell’illustrazione."}]},"assets/lezioni/scene-originali-20261028/lezione-astrofotografia.webp":{"points":[{"x":30,"y":31,"title":"Telefono fissato","text":"Il supporto impedisce movimenti durante la posa: non basta un appoggio precario."},{"x":32,"y":61,"title":"Cavalletto","text":"Tre appoggi stabili conservano l’inquadratura. Durata e direzione del campo incidono sulle scie."}]},"assets/lezioni/scene-originali-20261028/lezione-guide.webp":{"points":[{"x":34,"y":57,"title":"Osservazione condivisa","text":"Confrontarsi aiuta a distinguere riferimenti riconosciuti e dubbi."},{"x":56,"y":65,"title":"Appunti","text":"Una luce locale tenue permette di scrivere senza disturbare chi osserva vicino."}]},"assets/lezioni/scene-originali-20261028/lezione-strumentazione.webp":{"points":[{"x":33,"y":55,"title":"Focheggiatore","text":"Regola il piano di fuoco e deve sostenere il carico senza inclinazioni indesiderate."},{"x":66,"y":51,"title":"Camera collegata","text":"Attacchi, distanze e compatibilità fanno parte della catena ottica."}]},"assets/lezioni/scene-originali-20261028/lezione-1-2.svg":{"points":[{"x":29,"y":27,"title":"Altezza del polo","text":"L’angolo sopra l’orizzonte nord uguaglia la latitudine: qui 43° N."},{"x":36,"y":61,"title":"Asse terrestre","text":"La direzione polare è parallela all’asse terrestre. Non è l’obliquità rispetto all’orbita."}]},"assets/lezioni/scene-originali-20261028/lezione-1-5.svg":{"points":[{"x":67,"y":29,"title":"Terra a giugno","text":"Il lato notturno guarda un settore diverso del cielo: le stelle non vengono ridistribuite ogni stagione."},{"x":61,"y":50,"title":"Sole e direzione della notte","text":"Le frecce indicano la direzione del lato notturno, non velocità o forma esatta dell’orbita."}]},"assets/lezioni/scene-originali-20261028/lezione-1-6.svg":{"points":[{"x":26,"y":49,"title":"Orizzonte locale","text":"Piano e verticale dipendono da dove ti trovi sulla Terra."},{"x":74,"y":49,"title":"Equatore celeste","text":"Per le stelle lontane il riferimento si condivide a parità di sistema ed epoca."}]},"assets/lezioni/scene-originali-20261028/lezione-10-1.svg":{"points":[{"x":24,"y":46,"title":"Area coperta","text":"Un raggio planetario pari a un decimo di quello stellare copre un centesimo dell’area nel transito centrale ideale."},{"x":73,"y":56,"title":"Calo di luce","text":"La curva misura una diminuzione di flusso, non direttamente la massa del pianeta."}]},"assets/lezioni/scene-originali-20261028/lezione-10-2.svg":{"points":[{"x":21,"y":38,"title":"Luce assorbita","text":"L’energia ricevuta dipende da stella e distanza; una parte viene riflessa."},{"x":76,"y":48,"title":"Energia emessa","text":"Il pianeta riemette energia. L’equilibrio ideale non dà da solo la temperatura al suolo o la presenza di vita."}]},"assets/lezioni/scene-originali-20261028/lezione-10-3.svg":{"points":[{"x":19,"y":50,"title":"Massa minore","text":"Nel modello di Schwarzschild il raggio dell’orizzonte è proporzionale alla massa."},{"x":81,"y":50,"title":"Massa maggiore","text":"Dieci volte la massa dà dieci volte il raggio. Il disco non è una superficie materiale."}]},"assets/lezioni/scene-originali-20261028/lezione-10-5.svg":{"points":[{"x":29,"y":42,"title":"Bande assorbite","text":"Parte della radiazione non attraversa l’atmosfera: si osserva con strumenti sopra di essa."},{"x":58,"y":68,"title":"Finestre atmosferiche","text":"Visibile e alcune bande radio e infrarosse raggiungono il suolo. La trasparenza varia con la lunghezza d’onda."}]},"assets/lezioni/scene-originali-20261028/lezione-2-1.svg":{"points":[{"x":44,"y":47,"title":"Emisfero illuminato","text":"Il Sole illumina il lato rivolto verso di sé. I luoghi ruotano entrando e uscendo dalla luce."},{"x":59,"y":47,"title":"Emisfero notturno","text":"Il terminatore non è incollato a un meridiano terrestre."}]},"assets/lezioni/scene-originali-20261028/lezione-2-2.svg":{"points":[{"x":27,"y":49,"title":"Raggi meno inclinati","text":"Lo stesso fascio si distribuisce su meno terreno, concentrando l’energia."},{"x":73,"y":49,"title":"Raggi inclinati","text":"Il fascio si allarga sulla superficie. Nelle stagioni cambia anche la durata del dì."}]},"assets/lezioni/scene-originali-20261028/lezione-2-4.svg":{"points":[{"x":49,"y":44,"title":"Terra e orbita","text":"La luce viene sempre dalla stessa direzione. La fase dipende dalla parte illuminata rivolta a noi."},{"x":61,"y":81,"title":"Luna piena","text":"L’intero disco appare illuminato. Le fasi non sono causate dall’ombra della Terra."}]},"assets/lezioni/scene-originali-20261028/lezione-2-6.svg":{"points":[{"x":27,"y":49,"title":"Eclissi totale","text":"Il diametro apparente della Luna copre quello del Sole nell’allineamento illustrato."},{"x":73,"y":49,"title":"Eclissi anulare","text":"Se la Luna appare più piccola resta un anello di fotosfera: non è la corona della totalità."}]},"assets/lezioni/scene-originali-20261028/lezione-3-1.svg":{"points":[{"x":59,"y":30,"title":"Scala delle distanze","text":"Nella scala lineare i pianeti interni sono molto vicini. Qui si leggono distanze dal Sole."},{"x":59,"y":76,"title":"Scala dei diametri","text":"Questa seconda scala confronta dimensioni: non usarla per misurare le distanze superiori."}]},"assets/lezioni/scene-originali-20261028/lezione-3-6.svg":{"points":[{"x":52,"y":59,"title":"Sole al fuoco","text":"Il Sole occupa un fuoco dell’ellisse, non il centro."},{"x":59,"y":40,"title":"Aree e tempo","text":"Settori uguali corrispondono a tempi uguali: il pianeta si muove più rapido vicino al perielio."}]},"assets/lezioni/scene-originali-20261028/lezione-4-2.svg":{"points":[{"x":46,"y":48,"title":"Distanza d","text":"Si confronta il flusso che attraversa ogni unità di area."},{"x":81,"y":48,"title":"Distanza doppia","text":"L’area cresce di quattro volte: per la sorgente isotropa ideale il flusso diventa un quarto."}]},"assets/lezioni/scene-originali-20261028/lezione-4-4.svg":{"points":[{"x":24,"y":48,"title":"Raggio e temperatura","text":"Insieme determinano la potenza totale del modello."},{"x":69,"y":48,"title":"Più grande ma più fredda","text":"Dieci volte il raggio dà cento volte l’area; metà temperatura dà un sedicesimo di potenza per area. Il risultato è 6,25."}]},"assets/lezioni/scene-originali-20261028/lezione-6-3.svg":{"points":[{"x":10,"y":44,"title":"Due posizioni della Terra","text":"La base osservativa cambia con l’orbita. Distanze e spostamenti sono amplificati."},{"x":83,"y":49,"title":"Sfondo lontano","text":"La stella vicina cambia direzione rispetto allo sfondo. La parallasse annua è il semispostamento massimo."}]},"assets/lezioni/scene-originali-20261028/lezione-6-5.svg":{"points":[{"x":37,"y":29,"title":"Riga a riposo","text":"La lunghezza d’onda di riferimento è misurata in laboratorio."},{"x":48,"y":59,"title":"Riga osservata","text":"Lo spostamento relativo z può avere cause diverse: moto, espansione o gravità."}]},"assets/lezioni/scene-originali-20261028/lezione-7-1.svg":{"points":[{"x":13,"y":55,"title":"Occhio","text":"La misura è angolare: conta anche la distanza del riferimento dall’occhio."},{"x":67,"y":48,"title":"Riferimento di 8 cm","text":"A 60 cm sottende circa 7,6°. La mano personale va calibrata."}]},"assets/lezioni/scene-originali-20261028/lezione-7-4.svg":{"points":[{"x":27,"y":49,"title":"Campo ampio","text":"Il disco lunare di 0,5° entra nel campo di 2°."},{"x":73,"y":49,"title":"Campo stretto","text":"Il disco non entra nel campo di 0,4°. Ingrandimento e campo non aumentano insieme."}]},"assets/lezioni/scene-originali-20261028/lezione-8-5.svg":{"points":[{"x":40,"y":27,"title":"Ingresso nella goccia","text":"Il raggio si piega passando dall’aria all’acqua: rifrazione."},{"x":65,"y":54,"title":"Riflessione interna","text":"Dopo la riflessione raggiunge un’altra interfaccia ed esce con una nuova rifrazione."}]},"assets/lezioni/scene-originali-20261028/lezione-9-1.svg":{"points":[{"x":32,"y":48,"title":"Zenit","text":"Il centro è sopra l’osservatore, non il polo. La carta è calcolata per Roma alla data indicata."},{"x":8.75,"y":50.5,"title":"Est a sinistra","text":"È una vista verso il cielo. Ruotare la carta non significa specchiarla."}]},"assets/lezioni/scene-originali-20261028/lezione-9-2.svg":{"points":[{"x":75,"y":55,"title":"Altezza al transito","text":"Latitudine 45° e declinazione +20° danno 65° di altezza massima: stella ipotetica, non un orario civile."},{"x":70.8,"y":84.7,"title":"Orizzonte","text":"Altezza positiva non garantisce visibilità attraverso nubi e ostacoli."}]},"assets/lezioni/scene-originali-20261028/lezione-9-3.svg":{"points":[{"x":27,"y":49,"title":"Ora UTC","text":"Un riferimento comune per registrare l’istante."},{"x":73,"y":49,"title":"Ora civile italiana","text":"Nell’esempio in ora legale si aggiungono due ore. Controlla sempre data e fuso."}]},"assets/lezioni/scene-originali-20261028/lezione-9-4.svg":{"points":[{"x":23,"y":50,"title":"Piccola separazione","text":"I cateti di 30 e 40 secondi d’arco danno circa 50 secondi d’arco nel piano locale."},{"x":72,"y":48,"title":"Metadati","text":"Identità, sistema, epoca e condizioni devono essere compatibili per confrontare coordinate."}]},"assets/lezioni/scene-originali-20261028/lezione-9-5.svg":{"points":[{"x":35,"y":34,"title":"Altezze calcolate","text":"Le curve usano declinazioni assegnate e tempi relativi, non orari della tua città."},{"x":64,"y":73,"title":"Finestra operativa","text":"Una soglia aiuta a organizzare l’osservazione; il modello non calcola Sole, Luna o meteo reali."}]},"assets/lezioni/exploration-20261029/preparazione.webp":{"points":[{"x":49,"y":19,"title":"Tubo ottico e obiettivo","text":"La parte anteriore raccoglie luce. È una tipologia illustrativa senza prestazioni commerciali attribuite."},{"x":35,"y":25,"title":"Oculare e diagonale","text":"Il diagonale ripiega il cammino della luce per rendere comoda la posizione dell’occhio."},{"x":50,"y":33,"title":"Testa altazimutale","text":"Ruota in azimut e inclina il tubo in altezza: non è un’equatoriale orientata al polo."},{"x":41,"y":63,"title":"Gambe e serraggi","text":"Regola il sostegno prima del buio. La livella va sul piano indicato dal manuale: non basta appoggiarla al vassoio."},{"x":75,"y":72,"title":"Bussola","text":"Primo orientamento verso il nord magnetico: lontana dai metalli. Non sostituisce l’allineamento astronomico."}]},"assets/lezioni/exploration-20261029/gruppo.webp":{"points":[{"x":14,"y":27,"title":"Binocolo","text":"Comincia riconoscendo riferimenti con occhio nudo e binocolo."},{"x":43,"y":39,"title":"Spazio libero","text":"Attrezzatura e cavi non devono intralciare il passaggio."},{"x":63,"y":58,"title":"Appunti illuminati","text":"La luce deve servire il quaderno senza abbagliare: rossa e tenue, non soltanto rossa."},{"x":87,"y":66,"title":"Materiale ordinato","text":"Accessori raggiungibili riducono il bisogno di luci forti."},{"x":61,"y":18,"title":"Buio e adattamento","text":"La scena è al crepuscolo per mostrare i gesti. Per gli oggetti deboli attendi buio e adattamento degli occhi."}]},"assets/lezioni/exploration-20261029/kit.webp":{"points":[{"x":45,"y":66,"title":"Obiettivi del binocolo","text":"Le lenti anteriori raccolgono luce. Il diametro influisce anche su peso e luce raccolta."},{"x":29,"y":43,"title":"Rotella di fuoco","text":"Rende nitida una stella lontana; non regola l’ingrandimento."},{"x":33,"y":36,"title":"Oculari","text":"Adatta la distanza fra gli oculari ai tuoi occhi. La regolazione diottrica dipende dal modello."},{"x":64,"y":34,"title":"Carta sul telefono","text":"La schermata è illustrativa. In una vera app imposta luogo, data e ora e abbassa la luminosità."},{"x":71,"y":66,"title":"Quaderno","text":"Separa osservazione, interpretazione e domande. Puoi usare la scheda PDF della pagina."},{"x":85,"y":55,"title":"Lampada rossa","text":"Schermala e tienila tenue: anche il rosso troppo intenso abbaglia."},{"x":88,"y":37,"title":"Abbigliamento","text":"Giacca e copricapo aiutano da fermi al freddo. Considera vento, stagione e umidità."}]},"assets/lezioni/exploration-20261029/camere-digitali.webp":{"points":[{"x":33,"y":45,"title":"Sensore digitale","text":"La superficie rettangolare è il rivelatore. La luce diventa segnale digitale: non è pellicola."},{"x":38,"y":34,"title":"Baionetta","text":"Il collegamento deve rispettare attacco e distanza del piano del sensore."},{"x":67,"y":47,"title":"Finestra della camera astronomica","text":"La luce entra dall’apertura ottica; i cavi seguono collegamenti separati."},{"x":81,"y":35,"title":"Raffreddamento","text":"Dissipazione e controllo termico gestiscono alcuni contributi del sensore, non il rumore dei fotoni del cielo."},{"x":94,"y":40,"title":"Porta dati","text":"USB trasferisce dati. Alimentazione e connettore vanno verificati sul dispositivo reale."}]},"assets/lezioni/exploration-20261029/eq1-mount-with-aluminum-tripod.webp":{"points":[{"x":48,"y":18,"title":"Sostegno del tubo","text":"Gli anelli o l’attacco sostengono il tubo. Verifica sempre il serraggio prima di muovere il carico."},{"x":31,"y":65,"title":"Contrappeso","text":"Bilancia il tubo dall’altro lato dell’asse. Non aumenta la rigidità del treppiede."},{"x":57,"y":63,"title":"Regolazione di latitudine","text":"Inclina l’asse polare per il luogo. Questa regolazione di preparazione non è il movimento di inseguimento."}]},"assets/lezioni/exploration-20261029/eq2-mount-with-aluminum-tripod.webp":{"points":[{"x":58,"y":13,"title":"Attacco del tubo","text":"Qui il tubo viene fissato: l’insieme dei collegamenti porta il carico alla testa."},{"x":62,"y":44,"title":"Contrappeso","text":"Si sposta lungo l’asta per il bilanciamento."},{"x":48,"y":40,"title":"Comandi di movimento","text":"I comandi micrometrici consentono piccoli spostamenti; non sono un sistema GoTo automatico."}]},"assets/lezioni/exploration-20261029/eq3-mount-with-steel-tripod.webp":{"points":[{"x":45,"y":27,"title":"Testa equatoriale","text":"L’asse polare va orientato al polo celeste, non semplicemente verso una stella scelta a caso."},{"x":57,"y":41,"title":"Comando micrometrico","text":"Un comando regola un asse: riconoscere i due movimenti viene prima delle coordinate numeriche."},{"x":48,"y":75,"title":"Sostegno","text":"Stabilità e giunti sono importanti anche senza motori."}]},"assets/lezioni/exploration-20261029/eq5-mount-with-steel-tripod.webp":{"points":[{"x":56,"y":25,"title":"Testa tedesca","text":"Supporta il tubo su due assi perpendicolari. L’asse AR è inclinato verso il polo."},{"x":31,"y":52,"title":"Contrappesi","text":"Bilanciano il carico. La fotografia mostra l’assetto manuale, non una motorizzazione garantita."},{"x":51,"y":73,"title":"Base e regolazioni","text":"Le regolazioni di preparazione orientano l’asse polare. Non vanno confuse con i movimenti del tubo."}]},"assets/lezioni/exploration-20261029/heq5-synscan.webp":{"points":[{"x":52,"y":18,"title":"Sella del tubo","text":"L’attacco accoglie una barra compatibile. Le dimensioni dell’attacco vanno verificate."},{"x":65,"y":82,"title":"Pulsantiera","text":"Il controllo elettronico permette di comandare la montatura; l’allineamento iniziale resta necessario."},{"x":36,"y":52,"title":"Bilanciamento","text":"Contrappeso e carico devono essere equilibrati secondo il manuale."}]},"assets/lezioni/exploration-20261029/eq6r-pro.webp":{"points":[{"x":52,"y":17,"title":"Sella","text":"Sostiene tubo e accessori. La compatibilità della barra è una specifica meccanica."},{"x":41,"y":46,"title":"Corpo dell’asse polare","text":"L’orientamento di quest’asse permette l’inseguimento equatoriale dopo un allineamento corretto."},{"x":66,"y":82,"title":"Comando elettronico","text":"La pulsantiera controlla motori e puntamento: non sostituisce bilanciamento e preparazione."}]},"assets/lezioni/exploration-20261029/az4-with-steel-tripod.webp":{"points":[{"x":48,"y":34,"title":"Testa e movimento in altezza","text":"Il tubo può salire e scendere attorno a un asse orizzontale."},{"x":35,"y":67,"title":"Rotazione in azimut","text":"La base gira attorno alla verticale locale."},{"x":85,"y":25,"title":"Manico di puntamento","text":"Aiuta a orientare il carico con un movimento controllato."}]},"assets/lezioni/exploration-20261029/az-gti-mount.webp":{"points":[{"x":49,"y":29,"title":"Testa motorizzata","text":"La configurazione illustrata è altazimutale: altezza e azimut cambiano durante l’inseguimento."},{"x":49,"y":50,"title":"Colonna","text":"La colonna collega la testa al treppiede, non è l’asse polare di un’equatoriale."},{"x":49,"y":79,"title":"Treppiede","text":"Anche un sistema automatico richiede appoggi e serraggi stabili."}]},"assets/lezioni/exploration-20261029/az-eq6-synscan.webp":{"points":[{"x":46,"y":24,"title":"Assetto equatoriale","text":"In questa fotografia l’asse polare è inclinato. Il modello ha anche un diverso assetto altazimutale."},{"x":31,"y":48,"title":"Contrappesi","text":"Il loro uso dipende dalla configurazione scelta e dal manuale del modello."},{"x":49,"y":78,"title":"Controllo","text":"La modalità operativa corretta deve concordare con la configurazione meccanica."}]},"assets/lezioni/exploration-20261029/forcella-evolution.webp":{"points":[{"x":44,"y":30,"title":"Tubo Schmidt-Cassegrain","text":"Il tubo compatto usa un sistema catadiottrico: l’aspetto esterno non è una sezione del cammino ottico."},{"x":57,"y":48,"title":"Forcella a un braccio","text":"Il braccio orienta il tubo in altezza. La base non è inclinata su una testa equatoriale in questa foto."},{"x":49,"y":65,"title":"Base in azimut","text":"La base gira attorno alla verticale: la configurazione mostrata è altazimutale."}]},"assets/lezioni/montature-base.svg":{"points":[{"x":24.7,"y":42.3,"title":"Asse di altezza","text":"Il punto nel cerchio indica un asse diretto verso l’osservatore: il tubo ruota attorno a esso."},{"x":24.7,"y":56.7,"title":"Asse di azimut","text":"È verticale rispetto al piano dell’orizzonte locale."},{"x":76.6,"y":45.5,"title":"Asse di declinazione","text":"Anche questo asse esce dal piano meridiano ed è perpendicolare all’asse AR."},{"x":86,"y":33,"title":"Asse polare","text":"È parallelo all’asse terrestre e punta al polo celeste."},{"x":68,"y":61,"title":"Inclinazione di latitudine","text":"Nell’esempio l’asse polare è a 42° sull’orizzonte: non è l’obliquità terrestre di circa 23,4°."}]},"assets/lezioni/exploration-20261029/newton-quattro.webp":{"points":[{"x":21,"y":44,"title":"Supporto del secondario","text":"Le razze sostengono il piccolo specchio che devia la luce verso il focheggiatore laterale. Il primario è più in fondo al tubo."},{"x":48,"y":45,"title":"Focheggiatore laterale","text":"Qui si collega oculare o camera attraverso adattatori adatti. Le manopole regolano la posizione del piano di fuoco."},{"x":39,"y":21,"title":"Cercatore","text":"Il piccolo telescopio aiuta a riconoscere la direzione del tubo principale, dopo un allineamento reciproco."},{"x":45,"y":79,"title":"Anelli e barra","text":"Nella foto di catalogo sono mostrati anche separatamente. Nell’uso gli attacchi devono essere assemblati e serrati."}]},"assets/lezioni/exploration-20261029/sequenza-digitale.webp":{"points":[{"x":17,"y":17,"title":"Obiettivo e camera digitale","text":"La luce attraversa l’obiettivo e raggiunge il sensore, all’interno del corpo."},{"x":29,"y":32,"title":"Testa e blocco del cavalletto","text":"Il sostegno conserva l’inquadratura. Questo treppiede non segue il moto apparente delle stelle."},{"x":37,"y":19,"title":"Collegamento dati","text":"Il cavo parte dal lato della camera e conserva margine. Non deve tirare l’attrezzatura o entrare nel percorso ottico."},{"x":80,"y":56,"title":"Controllo della sequenza","text":"L’interfaccia è illustrativa, non una schermata di un’app specifica. Durata, intervallo e numero delle pose hanno funzioni diverse."},{"x":82,"y":74,"title":"Quaderno","text":"Conserva impostazioni, ora, condizioni e note sul bersaglio."},{"x":94,"y":69,"title":"Luce locale tenue","text":"Illumina solo ciò che serve e non gli occhi degli altri. Riduci anche la luminosità dello schermo."}]}};
